/**
 * Local exercise library.
 * Used by enrichPlan() to fill in instructions, formTips, media, and alternates
 * for exercises generated by AI — so the AI only needs to output name/sets/reps/rest.
 *
 * Each entry:
 *   name        — canonical display name
 *   aliases     — other names the AI might use for the same exercise
 *   instructions — 3–4 step-by-step setup/movement cues
 *   formTips    — 2 key form reminders
 *   mediaUrl    — YouTube search URL (always works, never goes dead)
 *   alternates  — 2 swap options with a note on when/why to use them
 */

function yt(query) {
  return `https://www.youtube.com/results?search_query=${encodeURIComponent(query + " exercise tutorial")}`;
}

