/**
 * Normalises a string for fuzzy matching:
 * lowercase, strip parentheses and their contents, collapse whitespace.
 */
function normalise(str) {
  return str
    .toLowerCase()
    .replace(/\(.*?\)/g, "")   // remove parenthetical e.g. "(Dumbbells)"
    .replace(/[^a-z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * findExercise — looks up an exercise in the library by name.
 * Matching strategy (in priority order):
 *   1. Exact canonical name match (case-insensitive)
 *   2. Alias match
 *   3. Normalised partial match (library name contained in input, or vice versa)
 * Returns the library entry or null if not found.
 */
export function findExercise(name) {
  if (!name) return null;
  const norm = normalise(name);

  // 1. Exact match on canonical name
  for (const ex of exerciseLibrary) {
    if (normalise(ex.name) === norm) return ex;
  }

  // 2. Alias match
  for (const ex of exerciseLibrary) {
    if (ex.aliases.some((a) => normalise(a) === norm)) return ex;
  }

  // 3. Partial match — library name appears in the input, or input appears in library name
  for (const ex of exerciseLibrary) {
    const libNorm = normalise(ex.name);
    if (norm.includes(libNorm) || libNorm.includes(norm)) return ex;
    if (ex.aliases.some((a) => { const an = normalise(a); return norm.includes(an) || an.includes(norm); })) return ex;
  }

  return null;
}
